<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_role(['admin','organizer']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']==='approved'?'approved':'rejected';$s=$pdo->prepare('UPDATE volunteer_applications SET status=? WHERE id=?');$s->execute([$status,(int)$_POST['id']]);flash('Application updated.');redirect('applications.php');}
$pageTitle='Applications';$rows=$pdo->query("SELECT va.id,va.status,va.message,u.name,u.email,u.student_no,e.title,e.event_date FROM volunteer_applications va JOIN users u ON u.id=va.student_id JOIN events e ON e.id=va.event_id ORDER BY va.created_at DESC")->fetchAll();require __DIR__.'/includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">VOLUNTEER MANAGEMENT</span><h1>Applications</h1><p>Review student applications and update their status.</p></section>
<div class="table-wrap"><table><thead><tr><th>Student</th><th>Event</th><th>Message</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?> · <?=e($r['student_no'])?></small></td><td><?=e($r['title'])?><small><?=e(date('d M Y',strtotime($r['event_date'])))?></small></td><td><?=e($r['message'])?></td><td><span class="status <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><?php if($r['status']==='pending'):?><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small btn-primary" name="status" value="approved">Approve</button><button class="btn btn-small btn-danger" name="status" value="rejected">Reject</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No applications yet.</td></tr><?php endif;?></tbody></table></div>
<?php require __DIR__.'/includes/footer.php';?>
